import 'package:audioplayers/audioplayers.dart';
import 'package:flutter/foundation.dart';

import 'settings.dart';

/// The game's sound effects. The files are generated by tool/generate_sounds.py.
enum Sfx {
  tap('tap.wav'),
  step('step.wav'),
  bump('bump.wav'),
  tryAgain('try_again.wav'),
  success('success.wav'),
  star('star.wav');

  const Sfx(this.file);
  final String file;
}

/// Plays sound effects according to the current [SettingsController] (on/off and volume).
/// Screens use this interface, so tests can swap in [RecordingSoundService].
abstract class SoundService {
  /// Plays [sfx] unless sound is off. Never throws: a missing sound must not break the game.
  Future<void> play(Sfx sfx);
}

class AudioSoundService implements SoundService {
  AudioSoundService(this._settings) {
    _settings.addListener(_onSettingsChanged);
  }

  final SettingsController _settings;
  // One player per effect, so a fast run of steps restarts its own sound instead of cutting off others.
  final Map<Sfx, AudioPlayer> _players = {};

  void _onSettingsChanged() {
    if (!_settings.value.soundEnabled) {
      for (final p in _players.values) {
        p.stop();
      }
    }
  }

  @override
  Future<void> play(Sfx sfx) async {
    final s = _settings.value;
    if (!s.soundEnabled || s.volume <= 0) return;
    try {
      final player = _players.putIfAbsent(sfx, () => AudioPlayer()..setReleaseMode(ReleaseMode.stop));
      await player.stop();
      await player.play(AssetSource('sounds/${sfx.file}'), volume: s.volume);
    } catch (e) {
      debugPrint('Could not play ${sfx.name}: $e');
    }
  }
}

/// Records what would have played. Used in tests.
class RecordingSoundService implements SoundService {
  RecordingSoundService(this._settings);

  final SettingsController _settings;
  final played = <Sfx>[];

  @override
  Future<void> play(Sfx sfx) async {
    if (_settings.value.soundEnabled) played.add(sfx);
  }
}
